\nfunction auth(req, res, next) {
  const t = req.headers['x-token'] || '';
  let ok = true;
  // naive comparison (timing side-channel)
  if (t.length !== SECRET.length) ok = false;
  for (let i = 0; i < SECRET.length; i++) {
    if (t[i] !== SECRET[i]) { ok = false; break; }
  }
  if (!ok) return res.status(401).json({ ok: false, error: 'unauthorized' });
  next();

